# frozen_string_literal: true
require "rails_helper"

RSpec.describe PaymentMailer, "during a Timekeeping handoff", type: :mailer do
  let(:company) { create :company }
  let(:client) { create :client, company: }
  let(:invoice) { create :invoice, client: }
  let(:user) { create(:user, current_workspace_id: company.id, companies: [company]) }

  # "Every invoice, line-item, invoice-tax and payment write, mobile-collection payments included,
  # gets 503 ownership_moving while handoff_step is set and writes nothing"
  it "refuses the payment mail during a handoff without setting payment_sent_at or sending mail" do
    user.add_role :admin, company
    expect(invoice.reload.payment_sent_at).to be_nil
    TimekeepingOwnership.current.update!(handoff_step: "settle")
    ActionMailer::Base.deliveries.clear

    expect do
      PaymentMailer.with(invoice_id: invoice.id, subject: "Paid").payment.deliver_now
    end.to raise_error(Timekeeping::BillingFence::OwnershipMoving)

    expect(invoice.reload.payment_sent_at).to be_nil
    expect(ActionMailer::Base.deliveries).to be_empty
  end
end

